c='p11';B='MẠNG 1'
def NET(items,h=250,w=520):
    # items: list of (x,y,w,h,text,fill,stroke); lines: ('L',x1,y1,x2,y2)
    out=''
    for it in items:
        if it[0]=='L': out+='<line x1="%d" y1="%d" x2="%d" y2="%d" stroke="#0B2545" stroke-width="3"/>'%it[1:]
        else:
            x,y,ww,hh,t,f,s=it; out+='<rect x="%d" y="%d" width="%d" height="%d" rx="9" fill="%s" stroke="%s" stroke-width="3"/><text x="%d" y="%d" text-anchor="middle" font-size="18" fill="#0B2545">%s</text>'%(x,y,ww,hh,f,s,x+ww//2,y+hh//2+6,t)
    return '<svg viewBox="0 0 %d %d" style="width:100%%"><g font-family="sans-serif" font-weight="800">%s</g></svg>'%(w,h,out)
PC=lambda x,y,t='Máy':(x,y,64,40,t,'#C8E6C9','#2E7D32')
S=[]
S.append(TITLE('TIN HỌC · MẠNG 1','THIẾT BỊ VÀ CẤU TRÚC<br>MẠNG MÁY TÍNH','Mạng máy tính, LAN – WAN, đường truyền có dây và không dây, thiết bị mạng (NIC, hub, switch, router, modem, AP, repeater), miền xung đột, cấu trúc hình sao và phân cấp.',['LAN','hub – switch','router','modem','miền xung đột']))
S.append(goals(c,B,['Nêu khái niệm <b>mạng máy tính</b>, phân biệt <b>LAN</b> và <b>WAN</b>.','Phân biệt các <b>đường truyền</b>: cáp xoắn, cáp quang, Wi-Fi, Bluetooth, 3G/4G/5G.','Nêu <b>chức năng</b> của NIC, hub, switch, router, modem, access point, repeater.','Giải thích <b>miền xung đột</b>; so sánh <b>hub và switch</b>.','Chọn thiết bị và đường truyền cho tình huống cụ thể.'],['Mạng, LAN, WAN','Đường truyền','Thiết bị mạng','Hub – switch','Chọn thiết bị']))
S.append(S2(c,B+' · 1','Mạng máy tính là gì?',card('Khái niệm',P('<b>Mạng máy tính</b>: tập hợp các máy tính và thiết bị được <b>nối với nhau</b> bằng đường truyền để <b>trao đổi dữ liệu, chia sẻ tài nguyên</b>.','Gồm: <b>thiết bị đầu cuối</b> (máy tính, điện thoại, máy in…), <b>thiết bị kết nối</b> (switch, router…), <b>đường truyền</b> và <b>giao thức</b>.','<b>Server</b>: hệ thống phần cứng và phần mềm cung cấp dịch vụ cho máy khách; mạng gia đình có thể không có server.')),NET([PC(10,20),PC(100,20),PC(190,20),(100,110,160,44,'Switch','#BBDEFB','#1565C0'),('L',42,60,150,110),('L',132,60,170,110),('L',222,60,200,110),(300,20,100,44,'Máy in','#FFF9C4','#F9A825'),('L',350,64,230,110),(300,110,160,44,'Router → Internet','#FFCDD2','#C62828'),('L',260,132,300,132)],190)+KEY('Mạng cho phép <b>dùng chung</b> máy in, tệp, Internet và trao đổi thông tin.')))
S.append(TB(c,B+' · 1','LAN và WAN',['','LAN (mạng cục bộ)','WAN (mạng diện rộng)'],[['<b>Phạm vi</b>','nhỏ: phòng, toà nhà, trường','lớn: thành phố, quốc gia, toàn cầu'],['<b>Sở hữu</b>','một tổ chức','nhiều tổ chức / nhà cung cấp'],['<b>Tốc độ</b>','cao','thường thấp hơn'],['<b>Ví dụ</b>','mạng phòng máy, mạng gia đình','<b>Internet</b>']],note=KEY('Internet là <b>mạng của các mạng</b> (WAN lớn nhất) nối vô số LAN.')))
S.append(S2(c,B+' · 2','Đường truyền có dây',card('Cáp xoắn và cáp quang',P('<b>Cáp xoắn</b> (đồng): rẻ, dễ lắp, hiệu quả tối đa khoảng <b>100 m</b>, dễ bị nhiễu điện từ; dùng nối máy vào switch.','<b>Cáp quang</b>: truyền <b>ánh sáng</b>, <b>xa</b> (hàng km), băng thông lớn, <b>không nhiễu điện từ</b>, khó bị lấy trộm tín hiệu.','Máy tính trong LAN dùng tín hiệu điện → muốn dùng quang phải có <b>bộ chuyển đổi quang – điện</b>.')),T(tr('Tiêu chí','Cáp xoắn','Cáp quang',h=True)+tr('Tín hiệu','điện','<b>ánh sáng</b>')+tr('Khoảng cách','~100 m','<b>rất xa</b>')+tr('Nhiễu điện từ','<b>có</b>','<b>không</b>')+tr('Chi phí','thấp','cao hơn')+tr('Dùng để','nối máy trong phòng','nối <b>các toà nhà</b>'))+KEY('Hai toà nhà cách <b>300 m</b>: ưu tiên <b>cáp quang</b>.')))
S.append(S2(c,B+' · 2','Đường truyền không dây',card('Wi-Fi, Bluetooth, mạng di động',P('<b>Wi-Fi</b> (Wireless Fidelity): bộ tiêu chuẩn truyền dữ liệu bằng <b>sóng vô tuyến</b>; thiết bị phát là <b>Access Point (AP)</b>.','<b>Bluetooth</b>: ~1 Mb/s, khoảng <b>10 m</b>, nối thiết bị cá nhân (tai nghe, chuột).','<b>Mạng di động</b>: 3G, 4G, 5G; <b>vệ tinh</b> cho vùng xa.')),T(tr('Chuẩn','Tốc độ tối đa',h=True)+tr('802.11b','11 Mb/s')+tr('802.11a, g','54 Mb/s')+tr('802.11n','450 Mb/s')+tr('802.11ac','1,3 Gb/s')+tr('<b>802.11ad</b>','4,6 Gb/s, dải <b>60 GHz</b>'))+KEY('Di động: <b>3G (40 Mb/s) → 4G (1,5 Gb/s) → 5G (10 Gb/s)</b>; 5G độ trễ rất thấp, hợp IoT.')))
S.append(S2(c,B+' · 2','Chọn đường truyền theo tình huống',card('Gợi ý',T(tr('Tình huống','Chọn',h=True)+tr('tai nghe không dây cách điện thoại 2 m','<b>Bluetooth</b>')+tr('nối hai toà nhà cách 300 m','<b>cáp quang</b>')+tr('nối máy vào switch trong phòng','<b>cáp xoắn</b>')+tr('chia sẻ ảnh giữa hai điện thoại cạnh nhau, không Internet','<b>Bluetooth / Wi-Fi Direct</b>')+tr('vùng không có cáp','vệ tinh, 4G/5G'))),KEY('Đề thường cho khoảng cách + yêu cầu và hỏi <b>công nghệ phù hợp nhất</b>.')))
S.append(S2(c,B+' · 3','Card mạng (NIC) và modem',card('Hai thiết bị đầu tiên',P('<b>Card mạng (NIC)</b>: thiết bị trong mỗi máy giúp máy <b>kết nối mạng</b>, mỗi NIC có <b>địa chỉ MAC</b> duy nhất.','<b>Modem</b>: <b>chuyển đổi</b> tín hiệu số ↔ tín hiệu của đường truyền (điện thoại, quang, di động), <b>giữ nguyên dữ liệu</b>; nằm giữa router và nhà cung cấp dịch vụ.','Loại: <b>ADSL</b> (dây điện thoại), <b>modem quang</b> (số ↔ quang), <b>modem GSM 3G/4G/5G</b> (có khe SIM).')),KEY('Chuyển đổi số ↔ tương tự (hoặc quang) là việc của <b>modem</b>; chọn đường đi là việc của <b>router</b>.')))
S.append(S2(c,B+' · 3','Hub và switch',card('Thiết bị tập trung kết nối',P('<b>Hub</b>: nhận tín hiệu ở một cổng rồi <b>phát ra mọi cổng khác</b> → mọi máy nối vào hub cùng <b>một miền xung đột</b>.','<b>Switch</b>: chỉ tạo <b>kênh tạm thời giữa cổng gửi và cổng nhận</b>; các cặp cổng khác vẫn truyền song song → mỗi cổng là một miền xung đột riêng.')),NET([PC(10,10,'A'),PC(90,10,'B'),(10,90,140,40,'HUB','#FFE0B2','#E65100'),('L',42,50,70,90),('L',122,50,110,90),(260,10,64,40,'C','#C8E6C9','#2E7D32'),(340,10,64,40,'D','#C8E6C9','#2E7D32'),(250,90,160,40,'SWITCH','#BBDEFB','#1565C0'),('L',292,50,310,90),('L',372,50,350,90)],150)+KEY('Hub: phát <b>ra mọi cổng</b>. Switch: <b>chỉ tới cổng đích</b>.')))
S.append(TB(c,B+' · 3','So sánh hub và switch',['','Hub','Switch'],[['<b>Cách chuyển</b>','phát ra <b>mọi cổng</b>','<b>kênh tạm</b> giữa hai cổng'],['<b>Miền xung đột</b>','<b>một</b> cho tất cả','<b>mỗi cổng</b> một miền'],['<b>Hiệu quả</b>','thấp, dễ xung đột khi nhiều máy','cao'],['<b>Dùng khi</b>','mạng rất nhỏ (gia đình ~4 máy), rẻ','văn phòng, phòng máy (hàng chục máy)']],note=KEY('A gửi B qua hub: C, D cùng nhận. Qua switch: <b>chỉ B</b> nhận (traffic không tràn sang máy khác).')))
S.append(S2(c,B+' · 3','Router: chọn đường giữa các mạng',card('Cổng LAN và cổng WAN',P('<b>Router</b> kết nối các <b>mạng khác nhau</b> và <b>chọn đường</b> (định tuyến) cho gói tin.','<b>Cổng WAN</b> nối ra ngoài (Internet); <b>cổng LAN</b> nối vào mạng nội bộ.','Dữ liệu từ máy A đến máy B ở LAN khác: vào router qua <b>cổng LAN</b>, ra qua <b>cổng WAN</b> thích hợp.','Router gia đình thường tích hợp <b>Wi-Fi (AP)</b>, <b>switch</b> và cả <b>modem</b>.')),NET([(10,20,110,44,'LAN A (máy A)','#C8E6C9','#2E7D32'),(190,10,140,64,'ROUTER','#FFCDD2','#C62828'),(400,20,110,44,'LAN B (máy B)','#C8E6C9','#2E7D32'),('L',120,42,190,42),('L',330,42,400,42),(215,110,90,30,'cổng LAN','#FFF9C4','#F9A825'),(335,100,90,30,'cổng WAN','#E1BEE7','#6A1B9A')],160)+KEY('Dấu hiệu nhận ra router: có <b>cổng WAN</b>. Hub/switch chỉ có các cổng như nhau.')))
S.append(S2(c,B+' · 3','Repeater và Access Point',card('Mở rộng phạm vi',P('<b>Repeater</b>: nhận tín hiệu yếu, <b>khuếch đại / chỉnh sửa</b> rồi phát lại → kéo dài khoảng cách. Quy tắc <b>5-4-3</b>: không quá 5 phân đoạn, <b>4 repeater</b>, 3 phân đoạn có máy.','<b>Access Point (AP)</b>: nối thiết bị <b>không dây</b> vào mạng có dây.','Cáp xoắn đã dài 100 m muốn thêm 100 m nữa: đặt <b>repeater</b> rồi nối thêm cáp.')),KEY('Thay bằng hub hay switch <b>không</b> làm tăng khoảng cách tối đa của một đoạn cáp xoắn.')))
S.append(S2(c,B+' · 4','Cấu trúc hình sao và phân cấp',card('Cách nối thiết bị',P('<b>Hình sao</b>: mọi máy nối vào một thiết bị trung tâm (switch): dễ thi công, rẻ, tin cậy, <b>dùng trong hầu hết LAN</b>.','<b>Phân cấp</b> = hình sao của các hình sao: mỗi tầng/phòng một switch nối lên switch tổng.','<b>Dạng tuyến, dạng vòng</b>: ít dùng cho nối máy; tuyến chủ yếu làm <b>đường trục</b> nối các toà nhà.')),NET([(190,20,140,40,'Switch tổng','#BBDEFB','#1565C0'),(10,110,110,40,'Switch tầng 1','#E3F2FD','#1565C0'),(205,110,110,40,'Switch tầng 2','#E3F2FD','#1565C0'),(400,110,110,40,'Switch tầng 3','#E3F2FD','#1565C0'),('L',260,60,65,110),('L',260,60,260,110),('L',260,60,455,110)],170)+KEY('Ba tầng, mỗi tầng một switch nối lên switch tổng: xung đột <b>chỉ nằm trong từng đường truyền</b>, không lan sang tầng khác.')))
S.append(S2(c,B+' · 4','Tình huống: chọn thiết bị',card('Hub hay switch?',P('<b>Nhà</b> có 4 thiết bị, chi phí thấp nhất: dùng <b>hub</b> được (ít máy, ít xung đột).','<b>Văn phòng</b> hàng chục máy dùng liên tục: dùng <b>switch</b>.','LAN từ vài chục đến hàng trăm máy nên dùng <b>switch</b>.')),T(tr('Hai máy','Phát biểu',h=True)+tr('A, B nối chung hub; C, D nối chung switch','A gửi B: <b>C, D</b> cũng nhận trên hub; trên switch <b>chỉ B</b> nhận')+tr('thay hai switch bằng hai hub','nguy cơ <b>xung đột tăng</b>'))))
S.append(SELF(c,B+' · 5','Tự kiểm tra: hub và switch','Điểm khác nhau cơ bản giữa hub và switch là gì? Với 3 tầng, mỗi tầng một switch nối lên switch tổng, miền xung đột thế nào?','',P('Hub phát tín hiệu ra <b>mọi cổng</b>; switch tạo <b>kênh tạm</b> giữa cổng gửi và nhận.','Xung đột chỉ nằm trong từng đường truyền giữa hai cổng, <b>không lan</b> sang tầng khác.'),22))
S.append(SELF(c,B+' · 5','Tự kiểm tra: router hay switch?','Dấu hiệu nào giúp nhận biết router chứ không phải switch?','',P('Router có <b>cổng WAN</b> nối ra ngoài mạng cục bộ.','“Có đèn ở mỗi cổng”, “có nhiều cổng RJ45” hay “nối nhiều máy bằng cáp xoắn” là đặc điểm chung với switch.'),22))
S.append(SELF(c,B+' · 5','Tự kiểm tra (HSG): đúng hay sai?','(a) Cáp quang dùng tín hiệu điện. (b) Modem chọn đường đi cho gói tin. (c) Router có cổng LAN và WAN. (d) Switch mở rộng một miền xung đột duy nhất. (e) Bluetooth phạm vi khoảng 10 m.','',P('(a) <b>Sai</b>: tín hiệu ánh sáng.','(b) <b>Sai</b>: đó là router.','(c) <b>Đúng</b>.','(d) <b>Sai</b>: switch <b>chia nhỏ</b> miền xung đột.','(e) <b>Đúng</b>.'),20))
